import type { Metadata } from "next";
import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import { getBillingOverview } from "@intelligo-dev/billing";

import { getPlans } from "@/lib/billing";
import { PricingContent } from "@/components/billing/pricing-content";

export async function generateMetadata(): Promise<Metadata> {
  const t = await getTranslations("pricing");
  return { title: t("meta.title") };
}

export default async function PricingPage() {
  const t = await getTranslations("pricing");
  const { workspace, membership } = await requireWorkspace();

  const [plans, overview] = await Promise.all([
    Promise.resolve(getPlans()),
    getBillingOverview({ workspaceId: workspace.id, role: membership.role }),
  ]);

  const currentPlanSlug =
    overview.role === "member" ? "free" : overview.planSlug;

  return (
    <div className="mx-auto w-full max-w-5xl space-y-8 p-4 md:p-10">
      <header className="space-y-2 text-center">
        <h1 className="text-3xl font-bold text-foreground md:text-4xl">
          {t("page.title")}
        </h1>
        <p className="text-base text-muted-foreground">
          {t("page.description")}
        </p>
      </header>

      <PricingContent
        plans={plans}
        currentPlanSlug={currentPlanSlug}
        canCheckout={membership.role === "owner"}
      />
    </div>
  );
}

import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";

export default function PricingLoading() {
  return (
    <div className="mx-auto w-full max-w-5xl space-y-8 p-4 md:p-10">
      <div className="space-y-2 text-center">
        <Skeleton className="mx-auto h-8 w-48" />
        <Skeleton className="mx-auto h-4 w-72" />
      </div>

      <div className="flex justify-center">
        <Skeleton className="h-10 w-64" />
      </div>

      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        {[1, 2, 3].map((i) => (
          <Card key={i} className="p-6">
            <div className="space-y-6">
              <div className="space-y-2">
                <Skeleton className="h-6 w-24" />
                <Skeleton className="h-4 w-full" />
              </div>
              <div className="space-y-2">
                <Skeleton className="h-10 w-32" />
              </div>
              <div className="space-y-3">
                {[1, 2, 3, 4].map((j) => (
                  <Skeleton key={j} className="h-4 w-full" />
                ))}
              </div>
              <Skeleton className="h-10 w-full" />
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}

"use client";

/** Error boundary for the pricing route. */

import { useEffect } from "react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/navigation";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

export default function PricingError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  const t = useTranslations("pricing");

  useEffect(() => {
    console.error("[pricing] error boundary caught:", error);
  }, [error]);

  return (
    <div className="flex min-h-96 items-center justify-center p-4">
      <div className="w-full max-w-md space-y-4">
        <Alert variant="destructive">
          <AlertDescription>{t("error.title")}</AlertDescription>
        </Alert>

        <div className="flex justify-center gap-3">
          <Button onClick={reset}>{t("error.tryAgain")}</Button>
          <Button
            variant="outline"
            render={<Link href="/" />}
            nativeButton={false}
          >
            {t("error.goHome")}
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Client wrapper around the plan grid: owns the monthly/yearly
 * interval selection and the "checkout was canceled" banner, both of
 * which need client state/searchParams the server-rendered page
 * doesn't have.
 */

import { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import { useTranslations } from "next-intl";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { AnimatedList, AnimatedListItem } from "@/components/ui/animated-list";
import type { PlanConfig } from "@intelligo-dev/billing/plans";

import { IntervalToggle } from "./interval-toggle";
import { PlanCard } from "./plan-card";

interface PricingContentProps {
  /** The plan catalogue, resolved by the page through `getPlans`. */
  plans: Partial<Record<string, PlanConfig>>;
  currentPlanSlug: string;
  canCheckout: boolean;
}

export function PricingContent({
  plans,
  currentPlanSlug,
  canCheckout,
}: PricingContentProps) {
  const t = useTranslations("pricing");
  const searchParams = useSearchParams();
  const [interval, setInterval] = useState<"monthly" | "yearly">("monthly");
  const hasIntervalPricing = Object.values(plans).some(
    (plan) =>
      plan !== undefined &&
      (plan.priceMonthly !== undefined || plan.priceYearly !== undefined)
  );
  const [showCanceled, setShowCanceled] = useState(false);

  useEffect(() => {
    if (searchParams.get("canceled") !== "true") return;
    setShowCanceled(true);
    const timeout = setTimeout(() => setShowCanceled(false), 5000);
    return () => clearTimeout(timeout);
  }, [searchParams]);

  const planEntries = Object.values(plans).filter((plan): plan is PlanConfig =>
    Boolean(plan)
  );

  return (
    <div className="space-y-8">
      {showCanceled && (
        <Alert>
          <AlertDescription>{t("content.canceled")}</AlertDescription>
        </Alert>
      )}

      {/* Hidden unless at least one plan is actually priced per period
          — a toggle that changes nothing is worse than no toggle. */}
      {hasIntervalPricing ? (
        <div className="flex justify-center">
          <IntervalToggle interval={interval} onChange={setInterval} />
        </div>
      ) : null}

      {/* Centred wrap rather than a grid: the catalogue can hold any
          number of plans, and fixed-width cards stay the same size
          whether there are two or five. */}
      <AnimatedList as="div" className="flex flex-wrap justify-center gap-6">
        {planEntries.map((plan) => (
          <AnimatedListItem as="div" key={plan.slug} className="w-full sm:w-80">
            <PlanCard
              plan={plan}
              currentPlanSlug={currentPlanSlug}
              interval={interval}
              canCheckout={canCheckout}
              // No plan is highlighted by default; set `isRecommended`
              // for the one you want to single out.
            />
          </AnimatedListItem>
        ))}
      </AnimatedList>
    </div>
  );
}

"use client";

/**
 * One plan's pricing card: name, price, feature list, and a checkout
 * CTA whose state depends on whether it's the workspace's current
 * plan, the free plan, or something the caller can afford to buy.
 *
 * The catalogue has no tier order, so every non-current, non-free plan
 * gets the same "switch to this plan" button. `plan.name`, `description`
 * and `features` are catalogue data rendered verbatim; only the card's
 * own badges and buttons are translated.
 */

import { Check } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";

import { CheckoutButton } from "./checkout-button";
import { CURRENCY } from "@/lib/billing-config";
import type { PlanConfig } from "@intelligo-dev/billing/plans";

interface PlanCardProps {
  plan: PlanConfig;
  currentPlanSlug: string;
  interval: "monthly" | "yearly";
  /** Whether the signed-in caller is allowed to start checkout (owner-only). */
  canCheckout: boolean;
  isRecommended?: boolean;
}

export function PlanCard({
  plan,
  currentPlanSlug,
  interval,
  canCheckout,
  isRecommended = false,
}: PlanCardProps) {
  const t = useTranslations("pricing");
  const format = useFormatter();
  const isCurrent = plan.slug === currentPlanSlug;

  // A plan with interval prices is quoted per period; one without is a
  // single purchase, and the toggle above is hidden for it entirely
  // (see pricing-content.tsx) so the label can't contradict the price.
  const intervalPrice =
    interval === "monthly" ? plan.priceMonthly : plan.priceYearly;
  const price = intervalPrice ?? plan.priceOneTime;
  const isFree = price === 0;
  const periodLabel =
    intervalPrice === undefined
      ? t("planCard.oneTime")
      : interval === "monthly"
        ? t("planCard.perMonth")
        : t("planCard.perYear");

  // Money is never rendered by a package helper: currency is a
  // deployment decision (`CURRENCY` in lib/billing-config.ts), and
  // "free" is copy, not a formatted zero.
  const priceLabel = isFree
    ? t("planCard.free")
    : format.number(price, {
        style: "currency",
        currency: CURRENCY,
        maximumFractionDigits: 0,
      });

  return (
    <Card
      className={`relative flex h-full flex-col p-6 ${
        isRecommended
          ? "border-2 border-foreground/30 shadow-lg dark:border-foreground/40"
          : ""
      }`}
    >
      {isRecommended && (
        <Badge className="absolute -top-3 left-1/2 -translate-x-1/2 bg-foreground text-background">
          {t("planCard.recommended")}
        </Badge>
      )}

      <div className="flex flex-1 flex-col space-y-6">
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-bold text-foreground">{plan.name}</h3>
            {isCurrent && (
              <Badge className="border border-border bg-accent text-muted-foreground">
                {t("planCard.current")}
              </Badge>
            )}
          </div>
          <p className="text-sm text-muted-foreground">{plan.description}</p>
        </div>

        <div className="space-y-1">
          <div className="flex items-baseline gap-1">
            <span className="text-4xl font-bold text-foreground">
              {priceLabel}
            </span>
            {!isFree && (
              <span className="text-sm text-muted-foreground">
                {periodLabel}
              </span>
            )}
          </div>
        </div>

        <ul className="space-y-3">
          {plan.features.map((feature) => (
            <li key={feature} className="flex items-start gap-2">
              <Check className="mt-0.5 size-4 flex-shrink-0 text-muted-foreground" />
              <span className="text-sm text-foreground">{feature}</span>
            </li>
          ))}
        </ul>

        <div className="mt-auto pt-2">
          {isCurrent ? (
            // Outline, not the default fill: the plan you are already
            // on is a statement of fact, and a solid disabled button
            // reads as the page's primary action greyed out.
            <Button disabled variant="outline" className="w-full">
              {t("planCard.currentPlanButton")}
            </Button>
          ) : isFree ? (
            <div className="py-2 text-center">
              <p className="text-sm text-muted-foreground">
                {t("planCard.freeForever")}
              </p>
            </div>
          ) : !canCheckout ? (
            <Button variant="outline" disabled className="w-full">
              {t("planCard.askOwner")}
            </Button>
          ) : (
            <CheckoutButton
              planSlug={plan.slug}
              interval={interval}
              className="w-full"
            >
              {t("planCard.switchTo", { planName: plan.name })}
            </CheckoutButton>
          )}
        </div>
      </div>
    </Card>
  );
}

"use client";

/** Monthly/yearly switch; the selected interval is the parent's state. */

import { useTranslations } from "next-intl";

import { Button } from "@/components/ui/button";

interface IntervalToggleProps {
  interval: "monthly" | "yearly";
  onChange: (interval: "monthly" | "yearly") => void;
}

export function IntervalToggle({ interval, onChange }: IntervalToggleProps) {
  const t = useTranslations("pricing");

  return (
    // Sized to its two words, not to the page; the parent centres it.
    <div className="inline-flex w-fit items-center gap-1 rounded-lg bg-muted p-1">
      <Button
        type="button"
        variant={interval === "monthly" ? "default" : "ghost"}
        size="sm"
        onClick={() => onChange("monthly")}
      >
        {t("intervalToggle.monthly")}
      </Button>
      <Button
        type="button"
        variant={interval === "yearly" ? "default" : "ghost"}
        size="sm"
        onClick={() => onChange("yearly")}
      >
        {t("intervalToggle.yearly")}
      </Button>
    </div>
  );
}

"use client";

/**
 * Triggers a Stripe subscription checkout for one plan/interval and
 * redirects the browser to the returned hosted checkout URL.
 */

import { useState } from "react";
import { useTranslations } from "next-intl";

import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";

import { createCheckoutSession } from "@/actions/billing";

interface CheckoutButtonProps {
  planSlug: string;
  interval: "monthly" | "yearly";
  children: React.ReactNode;
  disabled?: boolean;
  className?: string;
}

export function CheckoutButton({
  planSlug,
  interval,
  children,
  disabled,
  className,
}: CheckoutButtonProps) {
  const t = useTranslations("pricing");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleClick = async () => {
    setError(null);
    setIsLoading(true);

    const result = await createCheckoutSession({ planSlug, interval });

    if (!result.success) {
      setError(result.error);
      setIsLoading(false);
      return;
    }

    window.location.href = result.data.url;
  };

  return (
    <div className="space-y-2">
      <Button
        onClick={handleClick}
        disabled={disabled || isLoading}
        className={className}
      >
        {isLoading ? t("checkoutButton.redirecting") : children}
      </Button>

      {error && (
        <Alert variant="destructive">
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
    </div>
  );
}

"use server";

/**
 * Checkout server actions over `@intelligo-dev/billing`'s checkout service:
 * authorize, call the service, and map a `BillingServiceError` code to a
 * translated message. The `billing-settings` item imports this file too.
 */

import { headers } from "next/headers";
import { getTranslations } from "next-intl/server";
import { z } from "zod";

import { requireRole } from "@intelligo-dev/auth";
import {
  createBillingPortal,
  createCreditCheckout,
  createSubscriptionCheckout,
  isBillingServiceError,
} from "@intelligo-dev/billing";
import { getDefaultProductSlug } from "@intelligo-dev/billing/plans";

import { getCreditBundle } from "@/lib/billing";

export type BillingActionResult<T = { url: string }> =
  { success: true; data: T } | { success: false; error: string };

type Translator = Awaited<ReturnType<typeof getTranslations<"pricing">>>;

function friendlyMessage(t: Translator): Partial<Record<string, string>> {
  return {
    invalid_plan: t("errors.invalidPlan"),
    checkout_unavailable: t("errors.checkoutUnavailable"),
    invalid_bundle: t("errors.invalidBundle"),
    no_billing_account: t("errors.noBillingAccount"),
    provider_error: t("errors.providerError"),
  };
}

function friendlyError(error: unknown, t: Translator): string {
  if (isBillingServiceError(error)) {
    return friendlyMessage(t)[error.code] ?? error.message;
  }
  return error instanceof Error ? error.message : t("errors.genericFailure");
}

/**
 * This deployment's origin, for Stripe's success/cancel redirect URLs.
 *
 * `NEXT_PUBLIC_APP_URL` first: the `Host` header is whatever the client
 * sent, and a forged one points the post-payment redirect — which
 * carries `{CHECKOUT_SESSION_ID}` — at someone else's domain. The
 * header stays as the fallback for a deployment that has not set the
 * variable.
 */
async function origin(): Promise<string> {
  const configured = process.env.NEXT_PUBLIC_APP_URL;
  if (configured) return configured.replace(/\/+$/, "");

  const requestHeaders = await headers();
  const host = requestHeaders.get("host");
  const protocol = process.env.NODE_ENV === "production" ? "https" : "http";
  return `${protocol}://${host}`;
}

const checkoutSchema = z.object({
  planSlug: z.string().min(1),
  interval: z.enum(["monthly", "yearly"]).default("monthly"),
});

export type CheckoutActionInput = z.infer<typeof checkoutSchema>;

export async function createCheckoutSession(
  input: CheckoutActionInput
): Promise<BillingActionResult> {
  const t = await getTranslations("pricing");

  const parsed = checkoutSchema.safeParse(input);
  if (!parsed.success) {
    return {
      success: false,
      error: parsed.error.issues[0]?.message ?? t("errors.invalidInput"),
    };
  }

  try {
    const { workspace, user } = await requireRole(["owner"]);
    const base = await origin();

    const { url } = await createSubscriptionCheckout({
      workspaceId: workspace.id,
      userId: user.id,
      planSlug: parsed.data.planSlug,
      interval: parsed.data.interval,
      productSlug: getDefaultProductSlug(),
      successUrl: `${base}/checkout/success?session_id={CHECKOUT_SESSION_ID}`,
      cancelUrl: `${base}/pricing?canceled=true`,
    });

    return { success: true, data: { url } };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

const creditPurchaseSchema = z.object({
  bundleId: z.string().min(1),
});

export type CreditPurchaseActionInput = z.infer<typeof creditPurchaseSchema>;

export async function createCreditPurchaseSession(
  input: CreditPurchaseActionInput
): Promise<BillingActionResult> {
  const t = await getTranslations("pricing");

  const parsed = creditPurchaseSchema.safeParse(input);
  if (!parsed.success) {
    return {
      success: false,
      error: parsed.error.issues[0]?.message ?? t("errors.invalidInput"),
    };
  }

  const bundle = getCreditBundle(parsed.data.bundleId);
  if (!bundle) {
    return { success: false, error: t("errors.invalidBundle") };
  }

  try {
    const { workspace, user } = await requireRole(["owner"]);
    const base = await origin();

    const { url } = await createCreditCheckout({
      workspaceId: workspace.id,
      userId: user.id,
      bundle,
      successUrl: `${base}/settings/billing?credits=success`,
      cancelUrl: `${base}/settings/billing?credits=cancelled`,
    });

    return { success: true, data: { url } };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

export async function createPortalSession(): Promise<BillingActionResult> {
  const t = await getTranslations("pricing");

  try {
    const { workspace } = await requireRole(["owner"]);
    const base = await origin();

    const { url } = await createBillingPortal({
      workspaceId: workspace.id,
      returnUrl: `${base}/settings/billing`,
    });

    return { success: true, data: { url } };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

import "server-only";

/**
 * Server-side billing binding for the pricing, checkout and
 * billing-settings items. `getPlans`/`getPlan` read the catalogue your
 * composition root registered for the slug passed to
 * `setDefaultProductSlug`.
 *
 * To sell subscriptions only, delete `CreditBundles` and the
 * `createCreditPurchaseSession` action.
 */

import { getPlanBySlug, type PlanConfig } from "@intelligo-dev/billing";
import {
  getDefaultProductSlug,
  getProductPlans,
} from "@intelligo-dev/billing/plans";

export { CREDIT_BUNDLES, getCreditBundle } from "./billing-config";

/** The registered plan catalogue for this deployment's product. */
export function getPlans(): Partial<Record<string, PlanConfig>> {
  return getProductPlans(getDefaultProductSlug()) ?? {};
}

export function getPlan(slug: string): PlanConfig | null {
  return getPlanBySlug(slug, getDefaultProductSlug());
}

/**
 * Client-safe billing configuration, kept apart from the `server-only`
 * `lib/billing.ts` so client components can read it without pulling
 * Stripe into the browser bundle. A bundle is validated server-side by
 * `createCreditCheckout`.
 *
 * `CREDIT_BUNDLES` is the one-time credit packs you sell; edit or empty
 * it. A bundle's `name` is rendered verbatim, not translated.
 */

import { fromMajor } from "@intelligo-dev/core/money";
import type { CreditBundle } from "@intelligo-dev/billing";

/**
 * ISO 4217 code every money figure in the installed pages is formatted
 * in. It only affects display and converts nothing: it must match what
 * your payment provider charges in, and the `usdRateMicros` on the
 * billing settings row (editable in the admin console) must convert
 * model cost into it (1 for USD).
 */
export const CURRENCY = "USD";

/**
 * The buyer is charged `price` through the payment provider; the
 * workspace receives `grant` in the billing currency. They need not be
 * the same currency.
 */
export const CREDIT_BUNDLES: CreditBundle[] = [
  {
    id: "credits-small",
    name: "Small credit pack",
    grant: fromMajor(5, CURRENCY),
    price: fromMajor(5, "USD"),
  },
  {
    id: "credits-medium",
    name: "Medium credit pack",
    grant: fromMajor(13, CURRENCY),
    price: fromMajor(12, "USD"),
  },
  {
    id: "credits-large",
    name: "Large credit pack",
    grant: fromMajor(40, CURRENCY),
    price: fromMajor(35, "USD"),
  },
];

export function getCreditBundle(id: string): CreditBundle | undefined {
  return CREDIT_BUNDLES.find((bundle) => bundle.id === id);
}

/**
 * Formats money for display. Amounts are micros (millionths of one major
 * unit) with their currency; next-intl supplies the symbol, its position
 * and the separators from the reader's locale.
 *
 * Takes the formatter rather than calling a hook, so it serves a server
 * component (`await getFormatter()`) and a client one (`useFormatter()`).
 */

import type { useFormatter } from "next-intl";

/** next-intl's formatter, from `useFormatter()` or `getFormatter()`. */
type Formatter = ReturnType<typeof useFormatter>;

/** An amount in micros and the currency it is denominated in. */
export type MoneyLike = { amount: number; currency: string };

const MICROS_PER_UNIT = 1_000_000;

/** Two significant digits is enough to read a sub-cent amount by. */
const SIGNIFICANT_DIGITS = 2;

/** What `Intl` says this currency's minor unit is: 2 for USD, 0 for MNT. */
function currencyDigits(currency: string): number {
  return (
    new Intl.NumberFormat("en-US", {
      style: "currency",
      currency,
    }).resolvedOptions().maximumFractionDigits ?? 2
  );
}

/**
 * How many decimals this amount needs to be legible: the currency's
 * own, except when that would render a real charge as nothing. One chat
 * turn costs a fraction of a cent, and a usage page that says every
 * request cost $0.00 is worse than one that says $0.0048.
 */
export function moneyFractionDigits(value: MoneyLike): number {
  const digits = currencyDigits(value.currency);
  const major = Math.abs(value.amount) / MICROS_PER_UNIT;
  if (major === 0 || major >= 10 ** -digits / 2) return digits;
  const leadingZeros = Math.floor(-Math.log10(major));
  return Math.min(6, leadingZeros + SIGNIFICANT_DIGITS);
}

/**
 * Formats `value` in its own currency. To change options for every call
 * site (compact totals, say), edit this function.
 */
export function formatMoney(format: Formatter, value: MoneyLike): string {
  const digits = moneyFractionDigits(value);
  return format.number(value.amount / MICROS_PER_UNIT, {
    style: "currency",
    currency: value.currency,
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  });
}

